import {timeInfo} from './collection-time.js?v=20261017';
export function attachSurveyMap({$,state,auth,config,onFeature}){let map=null,base=null,drawn=[],focus=null,serial=0,busy=false,started=false,account=null,debounce=null,features=[],focusIssue=null;const chosenLabels=new Map(),chosenPhases=new Map();const status=t=>$('survey-map-status').textContent=t;
 const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('./vendor/leaflet.css',import.meta.url);document.head.append(css);
 function init(){if(map)return;map=L.map($('survey-map'),{preferCanvas:true}).setView([-1.94,29.87],9);map.attributionControl.setPrefix('Leaflet');base=L.tileLayer('https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:20,maxNativeZoom:19,attribution:'Imagery © Esri, Vantor, Earthstar Geographics and the GIS User Community',referrerPolicy:'no-referrer'}).addTo(map);base.on('tileerror',()=>{$('survey-map-base-status').textContent='Some basemap tiles could not load. Survey features remain available.';});map.on('moveend',()=>{if(started&&$('survey-map-auto').checked){clearTimeout(debounce);debounce=setTimeout(()=>load(false),700);}});$('survey-map-basemap').onchange=()=>{if($('survey-map-basemap').value==='none'){map.removeLayer(base);$('survey-map-base-status').textContent='Basemap hidden.';}else{base.addTo(map);$('survey-map-base-status').textContent='Satellite basemap: Esri World Imagery.';}};}
 function clear(){serial++;started=false;account=null;clearTimeout(debounce);if(map){for(const layer of drawn)map.removeLayer(layer);if(focus)map.removeLayer(focus);}drawn=[];features=[];$('survey-map-feature').replaceChildren(new Option('Load surveyed data first',''));$('survey-map-open-attributes').disabled=true;focus=null;focusIssue=null;$('survey-map-label-fields').replaceChildren();$('survey-map-phase-fields').replaceChildren();$('survey-map-phase-status').textContent='Load surveyed data to apply phase colours.';$('survey-map-label-status').textContent='';$('survey-map-selected').textContent='';$('survey-map-layers').replaceChildren();status('Selections changed. Load / refresh surveyed data to use the current layers, usernames and boundaries.');}
 function draw(shape,style){return shape.kind==='point'?L.circleMarker(shape.coordinates,{radius:5,...style}):shape.kind==='line'?L.polyline(shape.coordinates,style):L.polygon(shape.coordinates,style);}
 function labelChoice(layer){const name=chosenLabels.get(layer.url);return labelFields(layer.meta).some(f=>f.name===name)?name:layer.meta.objectIdField;}
 function updateLabels(){let shown=0;for(const feature of features){feature.item.unbindTooltip();if(!$('survey-map-labels').checked||!map.hasLayer(feature.item))continue;if(shown>=500)continue;const text=labelText(feature.layer.meta,feature.attributes,labelChoice(feature.layer));if(text){const node=document.createElement('span');node.textContent=text;feature.item.bindTooltip(node,{permanent:true,direction:'top',className:'network-label',opacity:.95});shown++;}}if(focus){focus.unbindTooltip();if($('survey-map-labels').checked&&focusIssue){const node=document.createElement('span');node.textContent='Selected feature';focus.bindTooltip(node,{permanent:true,direction:'bottom',className:'network-label'});}}$('survey-map-label-status').textContent=$('survey-map-labels').checked?'Showing '+shown+' feature label(s).'+(features.filter(f=>map.hasLayer(f.item)).length>500?' Labels are limited to the first 500 loaded features; zoom in to label a smaller area.':''):'Map labels are hidden. Choose a field for each layer, then turn labels on.';}
 $('survey-map-labels').onchange=updateLabels;
 $('survey-map-feature').onchange=()=>{$('survey-map-open-attributes').disabled=$('survey-map-feature').value==='';};$('survey-map-open-attributes').onclick=()=>{const choice=$('survey-map-feature').value,feature=choice!==''?features[Number(choice)]:null;if(!feature){status('Choose a surveyed feature first.');return;}onFeature(feature.issue);};
 function makeLabelControls(groups){$('survey-map-label-fields').replaceChildren();for(const {layer} of groups){const label=document.createElement('label'),select=document.createElement('select');label.textContent=layer.meta.name+' label field';select.setAttribute('aria-label',layer.meta.name+' label field');for(const field of labelFields(layer.meta))select.add(new Option((field.alias||field.name)+' ['+field.name+']',field.name));select.value=labelChoice(layer);select.onchange=()=>{chosenLabels.set(layer.url,select.value);load(false);};label.append(select);$('survey-map-label-fields').append(label);}}
 function phaseChoice(layer){const selected=chosenPhases.get(layer.url);return selected===undefined?phaseField(layer.meta):selected;}
 function styleFeatures(){const phaseMode=$('survey-map-colours').value==='phase';let single=0,three=0,unknown=0;for(const feature of features){const incomplete=feature.issue.fields.length>0,kind=feature.shape.kind,phase=phaseClass(feature.layer.meta,feature.attributes,phaseChoice(feature.layer));if(map.hasLayer(feature.item)){if(phase==='single')single++;else if(phase==='three')three++;else unknown++;}if(phaseMode)feature.item.setStyle(phaseStyle(kind,phase,incomplete));else{const color=incomplete?'#ff3030':kind==='line'?'#27d8ff':feature.layer.space==='Structure Junction'?'#ffffff':'#ffff00';feature.item.setStyle({color:kind==='point'?'#172d30':color,fillColor:color,fillOpacity:.95,weight:kind==='line'?3:1.5,dashArray:null});}if(feature.halo)feature.halo.setStyle({opacity:phaseMode ? .9 : 0});}const legend=$('survey-map-phase-status');legend.textContent=phaseMode?'Visible phase classes: '+single+' single-phase (blue), '+three+' three-phase (orange), '+unknown+' unknown / other (gray). Red outline or halo: missing monitored attributes. Magenta: selected alert.':'Monitoring colours: red missing attributes, yellow devices, white junctions, cyan lines; magenta selected alert.';}
 function phaseControls(groups){$('survey-map-phase-fields').replaceChildren();for(const {layer} of groups){const label=document.createElement('label'),select=document.createElement('select');label.textContent=layer.meta.name+' phase field';select.setAttribute('aria-label',layer.meta.name+' phase field');select.add(new Option('No phase classification',''));for(const field of labelFields(layer.meta).filter(f=>['esriFieldTypeString','esriFieldTypeInteger','esriFieldTypeSmallInteger','esriFieldTypeDouble'].includes(f.type)))select.add(new Option((field.alias||field.name)+' ['+field.name+']',field.name));select.value=phaseChoice(layer);select.onchange=()=>{chosenPhases.set(layer.url,select.value);load(false);};label.append(select);$('survey-map-phase-fields').append(label);}}
 $('survey-map-colours').onchange=styleFeatures;
 function record(layer,feature){const a=feature.attributes,fields=layer.fields.map(n=>layer.meta.fields.find(f=>f.name===n)).filter(Boolean),checked=checkedAttributes(layer.meta,a,fields),gid=globalIdField(layer.meta);return {key:JSON.stringify([layer.url,a[layer.meta.objectIdField],a[layer.source]]),layer:layer.meta.name,url:layer.url,id:a[gid?.name]||a[layer.meta.objectIdField],objectId:a[layer.meta.objectIdField],globalId:gid?a[gid.name]:null,globalIdField:gid?.name,user:a[layer.source]||'No tracking username',checkedAttributes:checked,fields:checked.filter(f=>f.kind).map(f=>f.name),missingFields:checked.filter(f=>f.kind).map(f=>({...f})),...timeInfo(layer.meta,a,layer.collected,Date.now())};}
 async function load(fit=false){if(busy){status('Map is loading. Refresh again when it finishes.');return;}busy=true;let version;try{init();const api=auth(),selection=await config();version=++serial;if(!selection.layers.length)throw Error('Choose monitoring layers first.');account=api;started=false;if(fit&&selection.geometry){const parts=selection.geometry.parts||[selection.geometry],rings=parts.flatMap(g=>g.rings);const points=rings.flat().map(p=>[p[1],p[0]]);map.fitBounds(L.latLngBounds(points),{padding:[18,18],maxZoom:16});}map.invalidateSize();status('Loading surveyed features in the visible map area…');const b=map.getBounds(),bounds={xmin:b.getWest(),ymin:b.getSouth(),xmax:b.getEast(),ymax:b.getNorth()},groups=[],notes=[],nextFeatures=[];let count=0,missing=0,limited=false;
 for(const layer of selection.layers){try{layer.labelField=labelChoice(layer);layer.phaseField=phaseChoice(layer);const data=await mapLayerRecords(api,layer,bounds,selection.spatial,selection.users);if(serial!==version||auth()!==api)return;const group=L.featureGroup();for(const feature of data.rows){const issue=record(layer,feature);issue.boundary=selection.label;const incomplete=issue.fields.length>0;count++;if(incomplete)missing++;const color=incomplete?'#ff3030':feature.shape.kind==='line'?'#27d8ff':layer.space==='Structure Junction'?'#ffffff':'#ffff00';let halo=null;if(incomplete&&feature.shape.kind!=='point'){halo=draw(feature.shape,{color:'#ff3030',weight:7,opacity:0,fill:false,interactive:false});group.addLayer(halo);}const item=draw(feature.shape,{color:feature.shape.kind==='point'?'#172d30':color,fillColor:color,fillOpacity:.95,weight:feature.shape.kind==='line'?3:1.5});const box=document.createElement('div'),title=document.createElement('strong'),text=document.createElement('p'),button=document.createElement('button');title.textContent=issue.layer;text.textContent='User: '+issue.user+'\nGlobal ID: '+(issue.globalId||'Not exposed')+'\n'+(fieldsMessage(issue));button.type='button';button.textContent='View attributes and attachments';button.onclick=()=>onFeature(issue);box.append(title,text,button);item.on('click',event=>{if($('survey-map-direct').checked){map.closePopup();onFeature(issue);}else L.popup().setLatLng(event.latlng).setContent(box).openOn(map);});nextFeatures.push({item,halo,shape:feature.shape,layer,issue,attributes:feature.attributes});group.addLayer(item);}groups.push({layer,group,count:data.rows.length});if(data.limited){limited=true;notes.push(layer.meta.name+': showing the first 10,000 of '+data.total+' matching features; zoom in.');}if(data.problems.length)notes.push(layer.meta.name+': '+data.problems.length+' unreadable/missing geometry record(s).');}catch(e){notes.push(layer.meta.name+': '+e.message);}}
 if(serial!==version||auth()!==api)return;for(const old of drawn)map.removeLayer(old);drawn=[];$('survey-map-layers').replaceChildren();for(const {layer,group,count} of groups){group.addTo(map);drawn.push(group);const label=document.createElement('label'),input=document.createElement('input');label.className='null-toggle';input.type='checkbox';input.checked=true;input.setAttribute('aria-label','Show map layer '+layer.meta.name);input.onchange=()=>{if(input.checked)group.addTo(map);else map.removeLayer(group);updateLabels();styleFeatures();};label.append(input,document.createTextNode(layer.meta.name+' ('+count+')'));$('survey-map-layers').append(label);}features=nextFeatures;$('survey-map-feature').replaceChildren(new Option('Choose a surveyed feature…',''),...features.map((f,i)=>new Option(f.issue.layer+' · '+f.issue.user+' · '+(f.issue.globalId||f.issue.objectId),String(i))));$('survey-map-open-attributes').disabled=true;makeLabelControls(groups);phaseControls(groups);updateLabels();styleFeatures();started=true;if(!map.getBounds().equals(b)&&$('survey-map-auto').checked){clearTimeout(debounce);debounce=setTimeout(()=>load(false),700);}status(count+' surveyed features shown in this map view; '+missing+' have missing monitored attributes. '+(selection.label?'Boundary: '+selection.label+'. ':'')+(notes.length?'Coverage incomplete / limited: '+notes.join(' '):'All accessible matching IDs in this view were processed.')+' Updated '+new Date().toLocaleTimeString('en-GB',{timeZone:'Africa/Kigali'})+' Kigali.');}catch(e){if(version===undefined||serial===version)status('Map unavailable: '+e.message);}finally{busy=false;}}
 function fieldsMessage(issue){return issue.checkedAttributes.length?(issue.fields.length?'Missing: '+issue.missingFields.map(f=>f.label).join(', '):'All selected monitoring attributes are filled.'):'No attribute rules selected for this layer.';}
 $('survey-map-load').onclick=()=>load(!started);$('survey-map-fit').onclick=()=>load(true);
 return {clear,refresh(){if(started&&$('survey-map-auto').checked)load(false);},checkSession(){if(account){try{if(auth()!==account)clear();}catch{clear();}}},async locate(issue){init();serial++;started=false;const api=auth(),meta=(await config()).layers.find(l=>l.url===issue.url)?.meta;if(!meta)throw Error('Select this alert layer to locate it on the monitor map.');const result=await api.request(issue.url+'/query',{objectIds:issue.objectId,outFields:[meta.objectIdField,issue.globalIdField].filter(Boolean).join(','),returnGeometry:true,outSR:4326});const f=result.features?.find(f=>f.attributes[meta.objectIdField]===issue.objectId);if(!f||!issue.globalIdField||String(f.attributes[issue.globalIdField]).replace(/[{}]/g,'').toLowerCase()!==String(issue.globalId).replace(/[{}]/g,'').toLowerCase())throw Error('Alert Global ID is no longer readable. Run a fresh check.');if(auth()!==api)throw Error('Sign-in changed.');const shape=mapGeometry({...f.geometry,spatialReference:f.geometry?.spatialReference||result.spatialReference});account=api;map.invalidateSize();if(focus)map.removeLayer(focus);focusIssue=issue;focus=draw(shape,{color:'#ff00dd',fillColor:'#ff00dd',fillOpacity:.6,weight:5,radius:10}).addTo(map);focus.on('click',()=>onFeature(issue));updateLabels();if(shape.kind==='point')map.setView(shape.coordinates,18);else map.fitBounds(focus.getBounds(),{padding:[40,40],maxZoom:18});$('survey-map-selected').textContent=issue.layer+' · '+issue.user+' · Global ID '+issue.globalId+' · '+fieldsMessage(issue);status('Alert feature highlighted in magenta. Load / refresh surveyed data to see surrounding selected network features.');$('survey-map-card').scrollIntoView({behavior:'smooth',block:'start'});},};}
